import {exchangeInventory} from './progression.mjs';
export const DECOR={
 autumnDecor:{name:'Herbstlicher Alp-Schmuck',season:'autumn',ingredients:{flower:4,fiber:4,wood:2},energy:3,text:'Blumenkübel, Erntekörbe und natürliche Kränze.'},
 halloweenDecor:{name:'Kürbisse & Kürbislichter',season:'autumn',ingredients:{pumpkin:3,wood:2,fiber:2},energy:4,text:'Kürbisgruppen und warme Lichter vor der Alphütte.'},
 christmasDecor:{name:'Winterliche Lichter & Kränze',season:'winter',ingredients:{wood:4,fiber:6,cloth:2},energy:5,text:'Lichterkränze und winterlicher Schmuck für Haus und Alp.'},
 christmasTree:{name:'Weihnachtsbaum im Holzkübel',season:'winter',ingredients:{wood:8,fiber:8,cord:3},energy:6,text:'Eine geschmückte Tanne mit Kugeln und warmen Lichtern.'}
};
export const freshDecoration=()=>({season:'autumn',unlocked:[],placed:[]});
export function validDecoration(d){return d&&['autumn','winter'].includes(d.season)&&['unlocked','placed'].every(k=>Array.isArray(d[k])&&d[k].length<=4&&new Set(d[k]).size===d[k].length&&d[k].every(id=>Object.hasOwn(DECOR,id)));}
export const ownsDecor=(s,id)=>!!s.inventory[id]||s.estate.decor.unlocked.includes(id);
export function decorAction(s,action,id){const d=s.estate.decor??=freshDecoration();if(action==='season'){if(!['autumn','winter'].includes(id))return{ok:false,message:'Unbekannte Dekosaison.'};d.season=id;return{ok:true,message:'Die Dekosaison ist gespeichert. Wetter und Tageszeit bleiben unabhängig.'};}if(!Object.hasOwn(DECOR,id))return{ok:false,message:'Unbekannte Dekoration.'};if(action==='craft'){if(s.position.region!=='alp'||!s.position.inside)return{ok:false,message:'Dekorationen entstehen an der Werkbank in der Alphütte.'};if(d.unlocked.includes(id))return{ok:false,message:'Diese Dekoration hast du bereits hergestellt.'};const r=exchangeInventory(s,{take:DECOR[id].ingredients,energy:DECOR[id].energy,stats:{crafts:1}});if(!r.ok)return r;d.unlocked.push(id);if(!d.placed.includes(id))d.placed.push(id);d.season=DECOR[id].season;return{ok:true,message:DECOR[id].name+' hergestellt, aufgestellt und gespeichert.'};}if(!ownsDecor(s,id))return{ok:false,message:'Stelle die Dekoration zuerst her oder kaufe sie am Dorfmarkt.'};if(action==='outdoor'){d.placed=d.placed.includes(id)?d.placed.filter(k=>k!==id):[...d.placed,id];d.season=DECOR[id].season;return{ok:true,message:'Aussendekoration gespeichert.'};}if(action==='indoor'){s.home.seasonalDecor=s.home.seasonalDecor===id?null:id;return{ok:true,message:'Dekoration für die Wohnstube gespeichert.'};}return{ok:false,message:'Unbekannte Aktion.'};}
